def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_colors = []
    for row in grid:
        if len(set(row)) == 1:
            sep_colors.append(row[0])
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            sep_colors.append(col[0])

    sep = max(set(sep_colors), key=sep_colors.count)
    row_cuts = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_cuts = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def segments(length, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append(list(range(start, cut)))
            start = cut + 1
        if start < length:
            result.append(list(range(start, length)))
        return result

    row_groups = segments(h, row_cuts)
    col_groups = segments(w, col_cuts)

    counts = {}
    for rs in row_groups:
        for cs in col_groups:
            for r in rs:
                for c in cs:
                    color = grid[r][c]
                    if color != sep:
                        counts[color] = counts.get(color, 0) + 1

    base = max(counts, key=counts.get)
    out = []
    for rs in row_groups:
        row = []
        for cs in col_groups:
            markers = sum(
                grid[r][c] != sep and grid[r][c] != base
                for r in rs for c in cs
            )
            row.append(1 if markers == 2 else base)
        out.append(row)
    return out
